icerik:
Bir dizinin kaç elemanlı olduğunu elle yazmak yerine .Length özelliği kullanılır:

for (int i = 0; i < sayilar.Length; i++)
{
    listBox1.Items.Add(sayilar[i]);
}

.Length kullanımı kodun dinamik ve hatasız olmasını sağlar.

Dizideki en büyük sayıyı bulmak için:
1. İlk elemanı lider (en büyük) kabul ederiz: int enBuyuk = sayilar[0];
2. Döngü ile diğer tüm odalara sırayla bakarız.
3. Eğer baktığımız oda liderden daha büyükse, yeni lider o olur: enBuyuk = sayilar[i];

private void btnCekilis_Click(object sender, EventArgs e)
{
    int[] sansliSayilar = new int[6];
    Random rnd = new Random();
    listBoxToplar.Items.Clear();

    // 1. Diziye Rastgele Sayıları Yükle ve Listele
    for (int i = 0; i < sansliSayilar.Length; i++)
    {
        sansliSayilar[i] = rnd.Next(1, 50); // 1-49 arası
        listBoxToplar.Items.Add((i + 1) + ". Şanslı Top: " + sansliSayilar[i]);
    }

    // 2. En Büyük / En Küçük Bulma
    int enBuyuk = sansliSayilar[0];
    int enKucuk = sansliSayilar[0];
    int toplam = 0;

    for (int i = 0; i < sansliSayilar.Length; i++)
    {
        if (sansliSayilar[i] > enBuyuk) enBuyuk = sansliSayilar[i];
        if (sansliSayilar[i] < enKucuk) enKucuk = sansliSayilar[i];
        toplam += sansliSayilar[i];
    }
    lblEnBuyuk.Text = "En Büyük Sayı: " + enBuyuk;
    lblEnKucuk.Text = "En Küçük Sayı: " + enKucuk;
    lblToplam.Text  = "Çekiliş Toplamı: " + toplam;
}

Dizideki her elemanı sırayla okumak için 'foreach' kullanılır:

string[] sehirler = { "Giresun", "Ordu", "Trabzon" };
foreach (string sehir in sehirler)
{
    listBox1.Items.Add(sehir);
}

foreach sadece okuma (read-only) yapar, diziye yeni değer yazamaz.

int[] notlar = { 70, 80, 90, 100 };
int toplam = 0;

for (int i = 0; i < notlar.Length; i++)
{
    toplam += notlar[i];
}
double ortalama = (double)toplam / notlar.Length;
lblOrtalama.Text = "Sınıf Ortalaması: " + ortalama.ToString("0.00");

